-- Oracle fixture (schema DBLENS_TEST, prefix META_). Run fixture_drop.sql first (or this is run after it).
-- @@ type_obj
CREATE OR REPLACE TYPE META_OBJ_T AS OBJECT (a NUMBER, b VARCHAR2(10))
-- @@ type_nest
CREATE OR REPLACE TYPE META_NEST_T AS TABLE OF NUMBER
-- @@ seq
CREATE SEQUENCE META_SEQ START WITH 100 INCREMENT BY 5 MINVALUE 1 MAXVALUE 99999 CYCLE CACHE 10
-- @@ dept
CREATE TABLE META_DEPT (
  id NUMBER GENERATED ALWAYS AS IDENTITY,
  name VARCHAR2(50) NOT NULL,
  CONSTRAINT META_DEPT_PK PRIMARY KEY (id),
  CONSTRAINT META_DEPT_NAME_UK UNIQUE (name)
)
-- @@ dept_cmt_t
COMMENT ON TABLE META_DEPT IS '部门表'
-- @@ dept_cmt_c1
COMMENT ON COLUMN META_DEPT.id IS '部门编号'
-- @@ dept_cmt_c2
COMMENT ON COLUMN META_DEPT.name IS '部门名称'
-- @@ emp
CREATE TABLE META_EMP (
  id NUMBER(19) NOT NULL,
  dept_id NUMBER,
  manager_id NUMBER(19),
  name VARCHAR2(100 CHAR) DEFAULT '无名' NOT NULL,
  salary NUMBER(10,2),
  created TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  notes CLOB,
  photo BLOB,
  name_upper VARCHAR2(100 CHAR) GENERATED ALWAYS AS (UPPER(name)) VIRTUAL,
  seq_no NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 10 INCREMENT BY 2),
  status VARCHAR2(10) DEFAULT ON NULL 'NEW',
  ref_no NUMBER DEFAULT META_SEQ.NEXTVAL,
  flag NUMBER(1) DEFAULT 0 NOT NULL,
  secret VARCHAR2(20) INVISIBLE,
  CONSTRAINT META_EMP_PK PRIMARY KEY (id),
  CONSTRAINT META_EMP_DEPT_FK FOREIGN KEY (dept_id) REFERENCES META_DEPT (id) ON DELETE CASCADE,
  CONSTRAINT META_EMP_MGR_FK FOREIGN KEY (manager_id) REFERENCES META_EMP (id) ON DELETE SET NULL,
  CONSTRAINT META_EMP_UK UNIQUE (dept_id, name),
  CONSTRAINT META_EMP_SAL_CK CHECK (salary >= 0),
  CONSTRAINT META_EMP_FLAG_CK CHECK (flag IN (0, 1))
)
-- @@ emp_cmt_t
COMMENT ON TABLE META_EMP IS '员工表 employee'
-- @@ emp_cmt_c
COMMENT ON COLUMN META_EMP.name IS '员工姓名'
-- @@ idx_created_desc
CREATE INDEX META_EMP_CREATED_IX ON META_EMP (created DESC)
-- @@ idx_upper
CREATE INDEX META_EMP_UPPER_IX ON META_EMP (UPPER(name))
-- @@ idx_composite_unique
CREATE UNIQUE INDEX META_EMP_UX ON META_EMP (dept_id, created, id)
-- @@ idx_bitmap
CREATE BITMAP INDEX META_EMP_STATUS_BX ON META_EMP (status)
-- @@ idx_fn_multi
CREATE INDEX META_EMP_FN2_IX ON META_EMP (dept_id, LOWER(name), salary * 2)
-- @@ idx_case_desc
CREATE INDEX META_EMP_CASE_IX ON META_EMP (CASE WHEN salary < 0 THEN 1 END DESC, dept_id)
-- @@ trg_row
CREATE OR REPLACE TRIGGER META_TRG_EMP
BEFORE INSERT OR UPDATE ON META_EMP
FOR EACH ROW
BEGIN
  :NEW.status := NVL(:NEW.status, 'NEW');
END; -- x
-- @@ trg_stmt
CREATE OR REPLACE TRIGGER META_TRG_EMP_STMT
AFTER DELETE OR INSERT ON META_EMP
BEGIN
  NULL;
END; -- x
-- @@ trg_all
CREATE OR REPLACE TRIGGER META_TRG_EMP_ALL
AFTER DELETE OR UPDATE OF salary, name OR INSERT ON META_EMP
FOR EACH ROW
WHEN (NEW.id > 0 OR OLD.id > 0)
BEGIN
  NULL;
END; -- x
-- @@ trg_compound
CREATE OR REPLACE TRIGGER META_TRG_EMP_CMP
FOR UPDATE OR DELETE ON META_EMP
COMPOUND TRIGGER
  AFTER STATISTICS IS BEGIN NULL; END AFTER STATISTICS;
END META_TRG_EMP_CMP; -- x
-- @@ view
CREATE OR REPLACE VIEW META_V_EMP AS
SELECT e.id, e.name, d.name AS dept_name FROM META_EMP e LEFT JOIN META_DEPT d ON d.id = e.dept_id
-- @@ view_cmt
COMMENT ON TABLE META_V_EMP IS '员工视图'
-- @@ trg_instead
CREATE OR REPLACE TRIGGER META_TRG_V_EMP
INSTEAD OF INSERT ON META_V_EMP
FOR EACH ROW
BEGIN
  NULL;
END; -- x
-- @@ mv
CREATE MATERIALIZED VIEW META_MV_DEPT AS SELECT id, name FROM META_DEPT
-- @@ mv_cmt
COMMENT ON MATERIALIZED VIEW META_MV_DEPT IS '部门物化视图'
-- @@ proc
CREATE OR REPLACE PROCEDURE META_P_META (p_x IN NUMBER) AS
BEGIN
  NULL;
END; -- x
-- @@ func
CREATE OR REPLACE FUNCTION META_F_META (p_x IN NUMBER) RETURN NUMBER AS
BEGIN
  RETURN p_x + 1;
END; -- x
-- @@ pkg
CREATE OR REPLACE PACKAGE META_PKG AS
  PROCEDURE do_it;
  FUNCTION get_it RETURN NUMBER;
END META_PKG; -- x
-- @@ pkg_body
CREATE OR REPLACE PACKAGE BODY META_PKG AS
  PROCEDURE do_it IS BEGIN NULL; END;
  FUNCTION get_it RETURN NUMBER IS BEGIN RETURN 1; END;
END META_PKG; -- x
-- @@ syn
CREATE SYNONYM META_SYN_EMP FOR META_EMP
-- @@ syn_remote
CREATE SYNONYM META_SYN_REMOTE FOR META_DEPT@meta_nolink
-- @@ part
CREATE TABLE META_PART_T (
  id NUMBER,
  d DATE NOT NULL
) PARTITION BY RANGE (d) (
  PARTITION p2024 VALUES LESS THAN (DATE '2025-01-01'),
  PARTITION p2025 VALUES LESS THAN (DATE '2026-01-01'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
)
-- @@ part_list
CREATE TABLE META_PART_L (
  id NUMBER,
  region VARCHAR2(10),
  d DATE
) PARTITION BY LIST (region) SUBPARTITION BY HASH (id) SUBPARTITIONS 2 (
  PARTITION pn VALUES ('N'),
  PARTITION ps VALUES ('S')
)
-- @@ iot
CREATE TABLE META_IOT (
  id NUMBER PRIMARY KEY,
  a VARCHAR2(2000),
  b VARCHAR2(2000)
) ORGANIZATION INDEX INCLUDING a OVERFLOW
-- @@ nest
CREATE TABLE META_NEST (
  id NUMBER,
  items META_NEST_T
) NESTED TABLE items STORE AS META_NEST_ITEMS
-- @@ gtt
CREATE GLOBAL TEMPORARY TABLE META_GTT (id NUMBER) ON COMMIT DELETE ROWS
-- @@ recycle
CREATE TABLE META_BIN (id NUMBER)
-- @@ recycle_drop
DROP TABLE META_BIN
-- @@ mixed
CREATE TABLE "Mixed Case" (
  "Id" NUMBER NOT NULL,
  "select" NUMBER,
  "数洞" VARCHAR2(10),
  "with space" VARCHAR2(5),
  CONSTRAINT "Mixed PK" PRIMARY KEY ("Id")
)
-- @@ mixed_cmt
COMMENT ON COLUMN "Mixed Case"."select" IS '保留字列'
-- @@ mixed_idx
CREATE INDEX "Mixed Idx" ON "Mixed Case" ("select", "数洞")
