  c_float_24 FLOAT(24),
  c_real REAL,
  c_double DOUBLE PRECISION,
  c_bfloat BINARY_FLOAT,
  c_bdouble BINARY_DOUBLE,
  c_char CHAR(10 BYTE),
  c_char_c CHAR(10 CHAR),
  c_varchar_b VARCHAR2(100 BYTE),
  c_varchar_c VARCHAR2(100 CHAR),
  c_nchar NCHAR(10),
  c_nvarchar NVARCHAR2(20),
