-- @@ longdef
DECLARE
  v_sql VARCHAR2(32000);
  v_def VARCHAR2(8000) := '''a''';
BEGIN
  FOR i IN 1 .. 1700 LOOP
    v_def := v_def || '||''''';
  END LOOP;
  v_sql := 'CREATE TABLE META_LONGDEF (id NUMBER, big VARCHAR2(4000) DEFAULT ' || v_def || ')';
  EXECUTE IMMEDIATE v_sql;
END; -- x
-- @@ view_big
DECLARE
  v_arr DBMS_SQL.VARCHAR2A;
  v_c INTEGER;
  v_n INTEGER := 0;
BEGIN
  v_n := v_n + 1; v_arr(v_n) := 'CREATE OR REPLACE VIEW META_V_BIG AS SELECT 1 AS id, ';
  FOR i IN 1 .. 450 LOOP
    v_n := v_n + 1; v_arr(v_n) := '/*' || RPAD('x', 100, 'y') || '*/' || CHR(10);
  END LOOP;
  v_n := v_n + 1; v_arr(v_n) := ' ''end'' AS big_text FROM dual';
  v_c := DBMS_SQL.OPEN_CURSOR;
  DBMS_SQL.PARSE(v_c, v_arr, 1, v_n, FALSE, DBMS_SQL.NATIVE);
  DBMS_SQL.CLOSE_CURSOR(v_c);
END; -- x
